const Portal={init:function(){"undefined"!=typeof firebase&&firebase.auth&&firebase.auth().onAuthStateChanged(t=>{const e=document.querySelectorAll(".portal-link");t?e.forEach(t=>{t.textContent="Go to Portal",t.href="parent-login.html"}):e.forEach(t=>{t.textContent="Parent Portal",t.href="parent-login.html"})})},login:async function(t,e){try{if("undefined"==typeof firebase||!firebase.auth)throw new Error("Firebase Auth SDK not initialized.");await firebase.auth().signInWithEmailAndPassword(t,e),window.location.href="parent-login.html"}catch(t){throw t}},logout:async function(){try{if("undefined"==typeof firebase||!firebase.auth)throw new Error("Firebase Auth SDK not initialized.");await firebase.auth().signOut(),window.location.href="index.html"}catch(t){console.error("Logout Error:",t)}}};document.addEventListener("DOMContentLoaded",Portal.init);